<?php $labels=['received'=>'Ti&#7871;p nh&#7853;n','checking'=>'&#272;ang ki&#7875;m tra','approved'=>'&#272;&#227; duy&#7879;t','assigned'=>'&#272;&#227; ph&#226;n c&#244;ng','in_progress'=>'&#272;ang x&#7917; l&#253;','completed'=>'&#272;&#227; nghi&#7879;m thu','rejected'=>'T&#7915; ch&#7889;i']; $workflow=['received'=>0,'checking'=>1,'approved'=>2,'assigned'=>3,'in_progress'=>4,'completed'=>5]; ?>
