<div class="panel" style="padding:18px;margin-bottom:16px"><h2 style="font-size:16px;margin:0 0 14px;color:var(--navy)">T&#7841;o phi&#7871;u b&#7843;o h&#224;nh</h2><form method="post" action="/admin/warranties" id="warrantyForm" style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px"><?= csrfField() ?>
  <div class="form-group" style="position:relative"><label>S&#7843;n ph&#7849;m *</label><input id="productSearch" autocomplete="off" placeholder="Nh&#7853;p t&#234;n, SKU ho&#7863;c m&#227; OEM" required><input type="hidden" name="product_id" id="productId"><div id="productSuggestions" style="display:none;position:absolute;z-index:20;left:0;right:0;top:100%;background:#fff;border:1px solid #d7deea;border-radius:6px;max-height:220px;overflow:auto"></div></div>
  <div class="form-group"><label>T&#234;n kh&#225;ch h&#224;ng *</label><input name="customer_name" required maxlength="100" placeholder="T&#7889;i &#273;a 100 k&#253; t&#7921;"></div>
  <div class="form-group"><label>S&#7889; &#273;i&#7879;n tho&#7841;i *</label><input name="customer_phone" required inputmode="numeric" maxlength="10" pattern="0[35789][0-9]{8}" placeholder="V&#237; d&#7909;: 0947123456"><small id="phoneHint" style="display:block;min-height:18px;margin-top:4px;color:#667085">G&#7891;m 10 s&#7889;, b&#7855;t &#273;&#7847;u: 03, 05, 07, 08 ho&#7863;c 09.</small></div>
