  <div class="form-group"><label>S&#7889; serial (n&#7871;u c&#243;)</label><input name="serial_no" maxlength="64"></div>
  <div class="form-group"><label>M&#227; &#273;&#417;n h&#224;ng (n&#7871;u c&#243;)</label><input name="order_code" maxlength="64"></div>
  <div class="form-group" style="grid-column:1/-1"><label>N&#7897;i dung y&#234;u c&#7847;u * <span id="wordCount" style="font-weight:400;color:#667085">0/200 t&#7915;</span></label><textarea name="issue_description" id="issueDescription" required rows="4" style="width:100%" placeholder="M&#244; t&#7843; l&#7895;i ho&#7863;c y&#234;u c&#7847;u b&#7843;o h&#224;nh"></textarea></div>
