</form></div>
<div class="panel"><div style="padding:14px 16px;border-bottom:1px solid var(--line);font-weight:700">Danh s&#225;ch phi&#7871;u b&#7843;o h&#224;nh (<?= count($cases) ?>)</div><div style="overflow:auto"><table class="tbl"><thead><tr><th>M&#227; phi&#7871;u</th><th>S&#7843;n ph&#7849;m</th><th>Kh&#225;ch h&#224;ng</th><th>H&#7841;n b&#7843;o h&#224;nh</th><th>Tr&#7841;ng th&#225;i</th><th>C&#7853;p nh&#7853;t</th></tr></thead><tbody>
<?php foreach($cases as $case): $current=$case['status'];$currentStep=$workflow[$current]??0;$terminal=in_array($current,['completed','rejected'],true); ?><tr><td><strong><?= e($case['case_code']) ?></strong><div class="fs-11 text-muted"><?= e($case['serial_no']?:'Khong co serial') ?></div></td><td><?= e($case['product_name']) ?><div class="fs-11 text-muted"><?= e($case['sku']) ?></div></td><td><?= e($case['customer_name']) ?><div class="fs-11 text-muted"><?= e($case['customer_phone']) ?><?= !empty($case['customer_email'])?' · '.e($case['customer_email']):'' ?></div></td><td><?= e($case['warranty_end_date']) ?></td><td><span style="font-size:11px;font-weight:700;color:<?= $terminal?'#667085':'#1565c0' ?>"><?= html_entity_decode($labels[$current]??$current,ENT_QUOTES,'UTF-8') ?></span></td><td><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><?php if($terminal): ?><span style="font-size:11px;color:#98a2b3;font-weight:700">Quy tr&#236;nh &#273;&#227; k&#7871;t th&#250;c</span><?php else: ?><form method="post" action="/admin/warranties/<?= (int)$case['id'] ?>/status" class="warranty-status-form" style="display:flex;gap:6px;align-items:center"><?= csrfField() ?><select name="status" data-current="<?= e($current) ?>"><?php foreach($labels as $key=>$label): $isPast=$key!=='rejected'&&isset($workflow[$key])&&$workflow[$key]<$currentStep; ?><option value="<?= $key ?>" <?= $current===$key?'selected':'' ?> <?= $isPast?'disabled':'' ?> style="<?= $isPast?'color:#98a2b3':'' ?>"><?= $isPast?'&#10003; &#272;&#227; qua - ':'' ?><?= html_entity_decode($label,ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-navy" disabled>L&#432;u</button></form><?php if(in_array($current,['approved','assigned','in_progress'],true)): ?><a class="btn btn-sm btn-outline-navy" href="/admin/warranties/<?= (int)$case['id'] ?>/materials">V&#7853;t t&#432;</a><?php endif; ?><?php endif; ?><a class="btn btn-sm btn-outline-navy" href="/admin/warranties/<?= (int)$case['id'] ?>/documents">Ch&#7913;ng t&#7915;</a></div></td></tr><?php endforeach; ?>
<?php if(!$cases): ?><tr><td colspan="6" style="text-align:center;padding:28px;color:#667085">Ch&#432;a c&#243; phi&#7871;u b&#7843;o h&#224;nh.</td></tr><?php endif; ?></tbody></table></div></div>
<script>(function(){var search=document.getElementById('productSearch'),productId=document.getElementById('productId'),box=document.getElementById('productSuggestions'),phone=document.querySelector('[name=customer_phone]'),phoneHint=document.getElementById('phoneHint'),issue=document.getElementById('issueDescription'),count=document.getElementById('wordCount'),timer;function escapeHtml(value){var node=document.createElement('div');node.textContent=value;return node.innerHTML}function words(){return issue.value.trim()?issue.value.trim().split(/\s+/).length:0}function renderCount(){var total=words();count.textContent=total+'/200 t\u1eeb';count.style.color=total>200?'#b42318':'#667085'}function validatePhone(){var value=phone.value.replace(/\D/g,'').slice(0,10);phone.value=value;var valid=/^0[35789]\d{8}$/.test(value);if(value!==''&&!valid){phone.setCustomValidity('S\u1ed1 \u0111i\u1ec7n tho\u1ea1i ph\u1ea3i c\u00f3 10 s\u1ed1 v\u00e0 b\u1eaft \u0111\u1ea7u b\u1eb1ng 03, 05, 07, 08 ho\u1eb7c 09.');phoneHint.textContent='S\u1ed1 ch\u01b0a h\u1ee3p l\u1ec7: ch\u1ec9 d\u00f9ng \u0111\u1ea7u 03, 05, 07, 08 ho\u1eb7c 09.';phoneHint.style.color='#b42318'}else{phone.setCustomValidity('');phoneHint.textContent='G\u1ed3m 10 s\u1ed1, b\u1eaft \u0111\u1ea7u: 03, 05, 07, 08 ho\u1eb7c 09.';phoneHint.style.color='#667085'}return valid}search.addEventListener('input',function(){productId.value='';clearTimeout(timer);var query=search.value.trim();box.style.display='none';if(query.length<2)return;timer=setTimeout(function(){fetch('/admin/warranties/products?q='+encodeURIComponent(query)).then(function(response){return response.json()}).then(function(items){box.innerHTML=items.map(function(item){return '<button type="button" data-id="'+item.id+'" data-label="'+escapeHtml(item.label)+'" style="display:block;width:100%;text-align:left;border:0;background:#fff;padding:9px 10px;cursor:pointer">'+escapeHtml(item.label)+'</button>'}).join('')||'<div style="padding:9px 10px;color:#667085">Kh\u00f4ng t\u00ecm th\u1ea5y s\u1ea3n ph\u1ea9m</div>';box.style.display='block'}).catch(function(){box.style.display='none'})},220)});box.addEventListener('click',function(event){var button=event.target.closest('button[data-id]');if(!button)return;productId.value=button.dataset.id;search.value=button.dataset.label;box.style.display='none'});phone.addEventListener('input',validatePhone);phone.addEventListener('blur',validatePhone);issue.addEventListener('input',renderCount);document.querySelectorAll('.warranty-status-form select').forEach(function(select){var button=select.form.querySelector('button');select.addEventListener('change',function(){button.disabled=select.value===select.dataset.current})});document.querySelectorAll('a[href*="/documents"]').forEach(function(link){var row=link.closest('tr'),select=row&&row.querySelector('.warranty-status-form select'),status=row&&row.querySelector('td:nth-child(5)'),completed=select?select.dataset.current==='completed':!!status&&status.textContent.trim()==='Đã nghiệm thu';if(!completed)link.remove()});document.getElementById('warrantyForm').addEventListener('submit',function(event){if(!productId.value){event.preventDefault();alert('H\u00e3y ch\u1ecdn m\u1ed9t s\u1ea3n ph\u1ea9m t\u1eeb danh s\u00e1ch g\u1ee3i \u00fd.');return}if(!validatePhone()){event.preventDefault();phone.reportValidity();return}if(words()>200){event.preventDefault();alert('N\u1ed9i dung y\u00eau c\u1ea7u t\u1ed1i \u0111a 200 t\u1eeb.')}});renderCount()})();</script>
